/**
 * hasRoleForUser determines whether a user has a role.
 *
 * @param name the user.
 * @param role the role.
 * @return whether the user has the role.
 */
public boolean hasRoleForUser(String name, String role) {
    List<String> roles = getRolesForUser(name);

    boolean hasRole = false;
    for (String r : roles) {
        if (r.equals(role)) {
            hasRole = true;
            break;
        }
    }

    return hasRole;
}

